.ds-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 10px 14px; min-height: 39px; border: 1px solid #2d3444; border-radius: 7px; background: #1a1f29; color: #ebedf2; font: 500 12px/1.3 "IBM Plex Sans", sans-serif; cursor: pointer; white-space: nowrap; transition: background 0.15s, border-color 0.15s; }
.ds-button:hover:not(:disabled) { background: #232a37; border-color: #465066; }
.ds-button:focus-visible { outline: 2px solid var(--accent, #ff7a1a); outline-offset: 3px; }
.ds-button:disabled { cursor: not-allowed; opacity: 0.45; }
@media (prefers-reduced-motion: reduce) { .ds-button { transition-duration: 0.01ms; } }
.ds-button.ds-primary { background: var(--accent, #ff7a1a); color: #140800; border-color: var(--accent, #ff7a1a); font-weight: 600; }
.ds-button.ds-primary:hover:not(:disabled) { background: #ff9138; border-color: #ff9138; }
.ds-button.ds-primary:disabled { background: #1a1f29; color: #939dad; border-color: #2d3444; }

