.ds-login-label { display: flex; flex-direction: column; gap: 8px; color: #c9d1df; font: 12px "IBM Plex Sans", sans-serif; }
.ds-login-field { box-sizing: border-box; width: 100%; min-width: 0; padding: 11px 12px; border: 1px solid #6b7588; border-radius: 6px; background: #0e1218; color: #f1f3f7; caret-color: #ff7a1a; font: inherit; }
.ds-login-field:focus-visible { outline: 2px solid var(--accent, #ff7a1a); outline-offset: 3px; }

.ds-nav-item { display: flex; align-items: center; gap: 12px; padding: 12px; border: 0; border-radius: 7px; background: linear-gradient(90deg, rgba(255, 122, 26, 0.16), rgba(255, 122, 26, 0.05)); box-shadow: inset 3px 0 0 #ff7a1a; color: #ffffff; font: 500 12px "IBM Plex Sans", sans-serif; text-align: left; cursor: pointer; }
.ds-nav-item svg { color: var(--accent, #ff7a1a); }
.ds-nav-item:focus-visible { outline: 2px solid var(--accent, #ff7a1a); outline-offset: 3px; }

.ds-status-set { display: flex; flex-wrap: wrap; gap: 12px; }
.ds-status { display: inline-flex; align-items: center; gap: 6px; color: #a6b0c0; font: 500 12px "IBM Plex Sans", sans-serif; white-space: nowrap; }
.ds-status::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: currentColor; flex-shrink: 0; }
.ds-online { color: var(--online, #ff8524); }
.ds-offline { color: var(--muted, #949eae); }
.ds-transition { color: var(--amber, #f7b955); }
.ds-error { color: var(--red, #f87a74); }

