.ds-card { padding: 24px; border: 1px solid var(--border, #232834); border-radius: var(--radius, 12px); background: var(--surface, #13171e); color: #f1f3f7; font: 12px "IBM Plex Sans", sans-serif; overflow: hidden; }
.ds-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.ds-card-head > div > span, .ds-card-metrics span { color: var(--muted, #949eae); }
.ds-card-head h2 { margin: 8px 0 0; font-size: 18px; font-weight: 600; letter-spacing: -0.015em; overflow-wrap: anywhere; }
.ds-card-head .ds-status { margin-top: 3px; }
.ds-card-metrics { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 15px; padding: 25px 0; margin-bottom: 20px; border-bottom: 1px solid var(--border, #232834); }
.ds-card-metrics > div { display: flex; flex-direction: column; gap: 10px; }
.ds-card-metrics strong { font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; }
.ds-actions { display: flex; align-items: center; gap: 8px; }
.ds-actions .ds-button { min-height: 36px; padding: 9px 12px; font-size: 11px; }
@media (max-width: 760px) { .ds-card { padding: 21px; } .ds-card-metrics { gap: 12px; } .ds-card-metrics strong { font-size: 14px; } .ds-actions { justify-content: space-between; } .ds-actions .ds-button { flex: 1; padding: 10px; min-height: 44px; } }

.ds-terminal { background: #080a0d; padding: 15px 14px; overflow: auto; overscroll-behavior: contain; font: 13px/1.7 "IBM Plex Mono", ui-monospace, SFMono-Regular, Consolas, monospace; }
.ds-log-line { display: grid; grid-template-columns: 65px 53px minmax(0, 1fr); gap: 9px; padding: 3px 0; align-items: start; }
.ds-log-line time { color: #7d8799; font-size: 11px; }
.ds-log-stream { color: #96a1b3; font-size: 11px; }
.ds-log-line code { color: #dce2ec; font: inherit; white-space: pre-wrap; overflow-wrap: anywhere; }
.ds-log-system code { color: #ffb878; }
@media (max-width: 760px) { .ds-terminal { padding: 10px; } .ds-log-line { grid-template-columns: 56px minmax(0, 1fr); gap: 6px; font-size: 12px; } .ds-log-stream { display: none; } }
